const camera=new T.PerspectiveCamera(47,innerWidth/innerHeight,.12,1200);
const sun=new T.DirectionalLight(0xffd396,3.3);sun.position.set(50,75,15);sun.castShadow=!mobile;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-85,right:85,top:95,bottom:-95,near:1,far:210});sun.shadow.bias=-.0003;sun.shadow.normalBias=.08;sun.target.position.set(0,0,-25);scene.add(sun,sun.target);
