function texture(kind){const c=document.createElement('canvas');c.width=c.height=512;const g=c.getContext('2d');g.fillStyle=kind==='stone'?'#777061':kind==='wood'?'#423022':'#7e6c4e';g.fillRect(0,0,512,512);for(let i=0;i<18000;i++){const v=40+rnd()*140;g.fillStyle=`rgba(${v},${v*.9},${v*.76},${rnd()*.14})`;g.fillRect(rnd()*512,rnd()*512,rnd()*8+1,rnd()*4+1)}if(kind==='stone'){for(let y=0;y<512;y+=64){for(let x=-128;x<512;x+=128){const xx=x+((y/64)%2)*64;g.strokeStyle='#36302b50';g.lineWidth=3;g.strokeRect(xx+1,y+1,125,61);g.strokeStyle='#b7aa8829';g.lineWidth=1;g.strokeRect(xx+3,y+3,121,57)}}}if(kind==='wood'){for(let i=0;i<160;i++){g.strokeStyle=`rgba(12,7,3,${rnd()*.2})`;g.beginPath();g.moveTo(0,rnd()*512);g.bezierCurveTo(130,rnd()*512,340,rnd()*512,512,rnd()*512);g.stroke()}}const t=new T.CanvasTexture(c);t.wrapS=t.wrapT=T.RepeatWrapping;t.colorSpace=T.SRGBColorSpace;return t}
const stoneTex=texture('stone'),woodTex=texture('wood');
const mat={stone:new T.MeshStandardMaterial({color:0x9e8b70,map:stoneTex,roughness:.92}),trim:new T.MeshStandardMaterial({color:0xceb991,map:stoneTex,roughness:.82}),dark:new T.MeshStandardMaterial({color:0x4b4038,map:stoneTex,roughness:.9}),roof:new T.MeshStandardMaterial({color:0x3b3432,roughness:.75,metalness:.12}),gold:new T.MeshStandardMaterial({color:0xc6a267,metalness:.74,roughness:.31}),bronze:new T.MeshStandardMaterial({color:0x74512b,metalness:.67,roughness:.38}),wood:new T.MeshStandardMaterial({color:0x856039,map:woodTex,roughness:.78}),green:new T.MeshStandardMaterial({color:0x314131,roughness:.94}),leaf:new T.MeshStandardMaterial({color:0x49523a,roughness:.86}),rose:new T.MeshStandardMaterial({color:0x8f3448,roughness:.78}),cream:new T.MeshStandardMaterial({color:0xdfbfa0,roughness:.88}),ground:new T.MeshStandardMaterial({color:0x4e4b33,roughness:1}),path:new T.MeshStandardMaterial({color:0x8f8069,map:stoneTex,roughness:.91}),window:new T.MeshBasicMaterial({color:0xedb25e}),wine:new T.MeshStandardMaterial({color:0x551d29,roughness:.88,side:T.DoubleSide}),parchment:new T.MeshStandardMaterial({color:0xd5b684,roughness:.9,side:T.DoubleSide})};
const unitBox=new T.BoxGeometry(),unitSphere=new T.SphereGeometry(1,12,8);
function add(geometry,material,pos=[0,0,0],scale=[1,1,1],rotation=[0,0,0],parent=null,dynamic=false){const m=new T.Mesh(geometry,material);m.position.set(...pos);m.scale.set(...scale);m.rotation.set(...rotation);m.castShadow=true;m.receiveShadow=true;if(parent||dynamic){(parent||scene).add(m);return m}m.updateMatrix();let arr=batches.get(material);if(!arr){arr=[];batches.set(material,arr)}const g=geometry.index?geometry.toNonIndexed():geometry.clone();g.applyMatrix4(m.matrix);arr.push(g);return m}
const box=(p,s,m=mat.stone,r=[0,0,0],parent)=>add(unitBox,m,p,s,r,parent);
