const cyl=(p,rt,rb,h,m=mat.stone,seg=20,parent)=>add(new T.CylinderGeometry(rt,rb,h,seg),m,p,[1,1,1],[0,0,0],parent);
function arch(x,y,z,r,depth=1,m=mat.trim){for(let i=0;i<20;i++){const a=(i+.5)/20*Math.PI;box([x+Math.cos(a)*r,y+Math.sin(a)*r,z],[r*.18,.62,depth],m,[0,0,a-Math.PI/2])}}
function column(x,z,h=9,y=0){cyl([x,y+h/2,z],.48,.62,h,mat.trim,12);box([x,y+.25,z],[1.6,.5,1.6],mat.dark);box([x,y+h,z],[1.5,.55,1.5],mat.trim);cyl([x,y+h-.5,z],.7,.7,.26,mat.gold,12)}
function balustrade(x,y,z,w,dir=0){const g=new T.Group();g.position.set(x,y,z);g.rotation.y=dir;for(let xx=-w/2;xx<=w/2;xx+=1.05){box([xx,.68,0],[.18,1.36,.22],mat.trim,[0,0,0],g);sphere([xx,.68,0],[.2,.26,.2],mat.trim,g)}box([0,1.42,0],[w+.5,.24,.42],mat.trim,[0,0,0],g);box([0,.06,0],[w+.5,.24,.5],mat.dark,[0,0,0],g);scene.add(g)}
function banner(x,y,z,w=2,h=6){const geom=new T.PlaneGeometry(w,h,7,14);const m=add(geom,mat.wine,[x,y,z],[1,1,1],[0,0,0],scene);const a=geom.attributes.position;const base=Float32Array.from(a.array);animations.push({kind:'cloth',m,base,w,h});box([x,y+h/2+.06,z],[w+.45,.13,.13],mat.gold);const emblem=new T.Mesh(new T.PlaneGeometry(.58,.8),new T.MeshBasicMaterial({color:0xbc9961,side:T.DoubleSide}));emblem.rotation.z=Math.PI/4;emblem.position.set(x,y+.45,z+.05);scene.add(emblem)}
const glowCanvas=document.createElement('canvas');glowCanvas.width=glowCanvas.height=64;const gc=glowCanvas.getContext('2d'),grad=gc.createRadialGradient(32,32,0,32,32,32);grad.addColorStop(0,'rgba(255,240,183,1)');grad.addColorStop(.15,'rgba(255,189,91,.75)');grad.addColorStop(1,'rgba(255,147,52,0)');gc.fillStyle=grad;gc.fillRect(0,0,64,64);const glowTex=new T.CanvasTexture(glowCanvas);
function candle(x,y,z,big=false){cyl([x,y+.22,z],.065,.08,.44,mat.cream,8);cyl([x,y-.02,z],.2,.16,.09,mat.gold,10);const s=new T.Sprite(new T.SpriteMaterial({map:glowTex,color:0xffc175,transparent:true,blending:T.AdditiveBlending,depthWrite:false}));s.position.set(x,y+.52,z);s.scale.set(big?1.6:.72,big?2.1:.92,1);scene.add(s);animations.push({kind:'flame',m:s,phase:rnd()*6,scale:s.scale.clone()})}
function tower(x,z,r,h){cyl([x,h/2,z],r,r*1.06,h,mat.stone,28);for(const yy of [1,h*.36,h*.7,h-1])cyl([x,yy,z],r*1.045,r*1.045,.48,mat.trim,28);cyl([x,h+.4,z],r*1.13,r,1.5,mat.dark,28);for(let i=0;i<12;i++){const a=i/12*Math.PI*2;box([x+Math.cos(a)*r,y0(h),z+Math.sin(a)*r],[1.45,1.65,1.1],mat.trim,[0,-a,0])}cyl([x,h+6.5,z],.12,r*1.12,12,mat.roof,28);sphere([x,h+12.6,z],.33,mat.gold);for(let a=0;a<Math.PI*2;a+=Math.PI/3){for(const yy of [h*.3,h*.57,h*.8]){const p=[x+Math.sin(a)*(r+.03),yy,z+Math.cos(a)*(r+.03)];box(p,[.72,1.8,.1],mat.window,[0,a,0]);box([p[0],yy,p[2]],[.09,1.85,.15],mat.bronze,[0,a,0])}}}function y0(h){return h+1.6}
// Landscape and the keep.
