box([0,.035,-16],[5,.04,76],mat.wine);for(const x of [-2.4,2.4])box([x,.065,-16],[.065,.01,76],mat.gold);
// Royal hall: high vault, stained light, dais, throne and velvet.
for(const x of [-12,12]){for(const z of [-45,-55,-64])column(x,z,14);if(x<0){box([x*1.15,7,-56],[1.2,14,24],mat.stone)}else{box([x*1.15,7,-65],[1.2,14,6],mat.stone);box([x*1.15,12,-53],[1.2,4,18],mat.stone)}}box([0,8,-67],[28,16,2],mat.stone);arch(0,10,-66,10,1.2);box([0,19,-55],[28,1,24],mat.roof);
box([0,.25,-58],[14,.5,12],mat.trim);box([0,.6,-61],[10,.4,5],mat.dark);box([0,2,-63],[2.6,2,2.6],mat.wine);box([0,4.4,-64],[2.8,5,.5],mat.gold);box([0,4.4,-63.65],[2.3,4.5,.25],mat.wine);for(const x of [-1.7,1.7]){box([x,2.2,-63],[.35,3.4,2.4],mat.gold);sphere([x,4,-63],.3,mat.gold)}
for(let x=-9;x<=9;x+=4.5){banner(x,10.8,-65.8,2.4,7);candle(x,1,-58,true)}
