function tree(x,z,h=7){cyl([x,h*.35,z],.18,.35,h*.7,mat.wood,7);for(let i=0;i<7;i++){const a=rnd()*6.28,r=rnd()*1.5;sphere([x+Math.cos(a)*r,h*.7+rnd()*1.9,z+Math.sin(a)*r],[1.5+rnd(),1.2+rnd(),1.5+rnd()],i%2?mat.green:mat.leaf)} }
