function memory(photo,p,w=3.2,rotation=0,parchment=false){const group=new T.Group();group.position.set(...p);group.rotation.y=rotation;scene.add(group);const ratio=photo.width/photo.height,h=w/ratio;box([0,0,-.11],[w+.55,h+.55,.2],parchment?mat.parchment:mat.wood,[0,0,0],group);if(!parchment){for(const sign of [-1,1]){box([sign*(w/2+.12),0,.045],[.2,h+.5,.18],mat.gold,[0,0,0],group);box([0,sign*(h/2+.12),.045],[w+.5,.2,.18],mat.gold,[0,0,0],group);box([sign*(w/2+.24),0,0],[.08,h+.6,.22],mat.bronze,[0,0,0],group);box([0,sign*(h/2+.24),0],[w+.6,.08,.22],mat.bronze,[0,0,0],group)}for(const xx of [-1,1])for(const yy of [-1,1])sphere([xx*(w/2+.1),yy*(h/2+.1),.16],.16,mat.gold,group)}const tex=loader.load(photo.src);tex.colorSpace=T.SRGBColorSpace;tex.anisotropy=Math.min(4,renderer.capabilities.getMaxAnisotropy());const face=new T.Mesh(new T.PlaneGeometry(w,h),new T.MeshBasicMaterial({map:tex,color:0xf6e7d2,side:T.DoubleSide}));face.position.z=.08;face.userData.photo=photo.id;group.add(face);photoMeshes.push(face);frames.push({group,base:group.position.clone(),rot:rotation,id:photo.id});return group}
