function character(src,height,outline){const geom=new T.BufferGeometry(),positions=[],uv=[],indices=[];const cx=512,cy=800;positions.push((cx/1024-.5)*height*2/3,(1-cy/1536)*height,0);uv.push(cx/1024,1-cy/1536);for(const [x,y] of outline){positions.push((x/1024-.5)*height*2/3,(1-y/1536)*height,0);uv.push(x/1024,1-y/1536)}for(let i=1;i<=outline.length;i++)indices.push(0,i,i===outline.length?1:i+1);geom.setAttribute('position',new T.Float32BufferAttribute(positions,3));geom.setAttribute('uv',new T.Float32BufferAttribute(uv,2));geom.setIndex(indices);geom.computeVertexNormals();const tex=loader.load(src);tex.colorSpace=T.SRGBColorSpace;const m=new T.Mesh(geom,new T.MeshBasicMaterial({map:tex,side:T.DoubleSide,color:0xf0d9bb}));m.frustumCulled=false;scene.add(m);return m}
